CREATE TABLE notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id UUID REFERENCES employees(id),type VARCHAR(80) NOT NULL,title VARCHAR(255) NOT NULL,body TEXT NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notification_deliveries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id UUID NOT NULL REFERENCES employees(id),channel VARCHAR(30) NOT NULL,notification_type VARCHAR(80) NOT NULL,logical_id VARCHAR(255) NOT NULL,payload JSONB NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),sent_at TIMESTAMPTZ,error TEXT,retry_count INT NOT NULL DEFAULT 0,UNIQUE(logical_id,channel,recipient_id));
CREATE TABLE telegram_links(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL UNIQUE REFERENCES employees(id),telegram_user_id BIGINT NOT NULL UNIQUE,telegram_chat_id BIGINT NOT NULL,linked_at TIMESTAMPTZ NOT NULL DEFAULT now(),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE telegram_link_tokens(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id),token_hash CHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE imports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),file_name VARCHAR(500) NOT NULL,type VARCHAR(80) NOT NULL,uploaded_by VARCHAR(255) NOT NULL,uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(),rows_total INT NOT NULL DEFAULT 0,success_count INT NOT NULL DEFAULT 0,warning_count INT NOT NULL DEFAULT 0,error_count INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL);
CREATE TABLE import_errors(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),import_id UUID NOT NULL REFERENCES imports(id) ON DELETE CASCADE,row_number INT,column_name VARCHAR(255),value TEXT,problem TEXT NOT NULL,suggested_fix TEXT);
CREATE TABLE audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor VARCHAR(255),action VARCHAR(100) NOT NULL,target VARCHAR(100),target_id UUID,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),metadata JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE system_settings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),setting_key VARCHAR(100) NOT NULL UNIQUE,setting_value TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_by VARCHAR(255));